/* ---------------------------------------------------------------------
   0. CAPA DE PERSISTENCIA — con caché en memoria y 4 motores posibles,
   detectados y conectados automáticamente en este orden de prioridad:
     1) Servidor local (server.js) — un archivo de base de datos DENTRO
        de la misma carpeta del sistema (data/sigie-datos.json). Es el
        modo recomendado: al copiar toda la carpeta a otra computadora,
        la base de datos viaja con ella.
     2) Firebase Firestore (nube compartida entre todas las computadoras,
        requiere internet y credenciales propias configuradas)
     3) window.storage de Claude (si se está usando dentro del chat)
     4) localStorage del navegador (respaldo si no hay red / no hay Claude
        ni servidor local corriendo)
   El resto del sistema (DB.load / DB.save / DB.delete) no sabe ni le
   importa cuál de los cuatro está activo: siempre usa el mismo objeto STORAGE.
   --------------------------------------------------------------------- */
// Si la sesión terminó (cookie vencida, servidor reiniciado, usuario eliminado…) volvemos al login.
function irALogin(){
  if(/login\.html$/.test(location.pathname)) return;
  const pag = location.pathname.split('/').pop();
  window.location.href = 'login.html' + (pag==='modo-rapido.html' ? '?next=modo-rapido.html' : '');
}
const ServerBackend = {
  base: '/api/db',
  // Todas las llamadas pasan por aquí: sin sesión (401) o con contraseña provisional pendiente → al login.
  async _fetch(url, opts) {
    const r = await fetch(url, opts);
    if (r.status === 401) { irALogin(); const e = new Error('Tu sesión terminó. Vuelve a iniciar sesión.'); e.noReintentar = true; throw e; }
    if (r.status === 403) {
      let d = {}; try { d = await r.clone().json(); } catch (x) {}
      if (d.codigo === 'CAMBIO_CLAVE') { irALogin(); }
      const e = new Error(d.error || 'No tienes permiso para esa operación.'); e.noReintentar = true; throw e;
    }
    return r;
  },
  async get(key) {
    const r = await this._fetch(this.base + '/item?key=' + encodeURIComponent(key), { cache: 'no-store' });
    if (r.status === 404) throw new Error('key not found: ' + key); // mismo comportamiento que window.storage
    if (!r.ok) throw new Error('el servidor local respondió con error ' + r.status);
    const data = await r.json();
    return { key, value: data.value, version: data.version, shared: false };
  },
  // baseVersion: versión que este navegador había leído. Si otro guardó después, el servidor responde 409
  // y DB.save fusiona los dos cambios. Sin baseVersion (undefined) la escritura es incondicional (restaurar, reiniciar…).
  async set(key, value, _shared, baseVersion) {
    const cuerpo = { key, value };
    if (baseVersion !== undefined) cuerpo.baseVersion = baseVersion;
    const r = await this._fetch(this.base + '/item', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(cuerpo)
    });
    if (r.status === 409) {
      const d = await r.json();
      const e = new Error('conflicto de versión'); e.conflicto = true; e.version = d.version; e.valorServidor = d.value; throw e;
    }
    if (r.status === 400 || r.status === 413) {
      let d = {}; try { d = await r.json(); } catch (x) {}
      const e = new Error(d.error || ('el servidor rechazó los datos (' + r.status + ')')); e.noReintentar = true; throw e;
    }
    if (!r.ok) throw new Error('el servidor local respondió con error ' + r.status);
    const d = await r.json();
    return { key, value, version: d.version, shared: false };
  },
  async delete(key) {
    const r = await this._fetch(this.base + '/item?key=' + encodeURIComponent(key), { method: 'DELETE' });
    if (!r.ok && r.status !== 404) throw new Error('el servidor local respondió con error ' + r.status);
    return { key, deleted: true, shared: false };
  },
  async list(prefix) {
    const r = await this._fetch(this.base + '/list' + (prefix ? ('?prefix=' + encodeURIComponent(prefix)) : ''), { cache: 'no-store' });
    if (!r.ok) throw new Error('el servidor local respondió con error ' + r.status);
    const data = await r.json();
    return { keys: data.keys || [], prefix, shared: false };
  },
  async versiones() {
    const r = await this._fetch(this.base + '/versions', { cache: 'no-store' });
    if (!r.ok) throw new Error('error ' + r.status);
    return (await r.json()).versions || {};
  }
};
// Detecta si el sistema se está abriendo a través de server.js (http://localhost:...)
// preguntándole al endpoint de salud. Si el sistema se abrió con doble clic
// directo al .html (file://) o el servidor no está corriendo, esto falla
// rápido y el sistema sigue de largo hacia Firebase/localStorage sin trabarse.
async function intentarConectarServidorLocal() {
  try {
    if (location.protocol !== 'http:' && location.protocol !== 'https:') return false;
    const r = await fetch('/api/health', { cache: 'no-store' });
    if (!r.ok) return false;
    const data = await r.json();
    return !!(data && data.ok);
  } catch (e) { return false; }
}
