const FIRESTORE_COLECCION = 'sigie_kv'; // una sola colección tipo "clave -> valor"

let firestoreDb = null;
const FirestoreBackend = {
  async get(key){
    const doc = await firestoreDb.collection(FIRESTORE_COLECCION).doc(key).get();
    if(!doc.exists) throw new Error('key not found: '+key); // mismo comportamiento que window.storage
    return { key, value: doc.data().value, shared:true };
  },
  async set(key, value){
    await firestoreDb.collection(FIRESTORE_COLECCION).doc(key).set({ value, actualizado: Date.now() });
    return { key, value, shared:true };
  },
  async delete(key){
    await firestoreDb.collection(FIRESTORE_COLECCION).doc(key).delete();
    return { key, deleted:true, shared:true };
  },
  async list(prefix){
    let query = firestoreDb.collection(FIRESTORE_COLECCION);
    if(prefix){ query = query.orderBy(firebase.firestore.FieldPath.documentId()).startAt(prefix).endAt(prefix+'\uf8ff'); }
    const snap = await query.get();
    return { keys: snap.docs.map(d=>d.id), prefix, shared:true };
  }
};
// Intenta conectar a Firebase; si el SDK no cargó (bloqueado por el sandbox de la
// vista previa de Claude, sin internet, o rechazado por las reglas de Firestore)
// devuelve false SIN romper nada, para que el sistema use el siguiente respaldo.
async function intentarConectarFirebase(){
  try{
    if(typeof firebase === 'undefined') return false;
    if(!firebase.apps || !firebase.apps.length){ firebase.initializeApp(FIREBASE_CONFIG); }
    await firebase.auth().signInAnonymously();
    firestoreDb = firebase.firestore();
    // Nota: Firestore reserva cualquier ID de documento que empiece Y termine
    // con doble guion bajo (p.ej. "__ping__"), lo rechaza con "reserved id".
    // Por eso el ID de prueba usa un solo guion bajo al inicio y al final.
    await firestoreDb.collection(FIRESTORE_COLECCION).doc('_ping_').set({ ts: Date.now() });
    return true;
  }catch(e){
    console.warn('Firebase no disponible, se usará almacenamiento alterno:', e && e.message);
    return false;
  }
}

const LocalStorageBackend = {
  async get(key){
    const raw = window.localStorage.getItem(key);
    if(raw === null) throw new Error('key not found: '+key); // mismo comportamiento que window.storage
    return { key, value: raw, shared:false };
  },
  async set(key, value){ window.localStorage.setItem(key, value); return { key, value, shared:false }; },
  async delete(key){ window.localStorage.removeItem(key); return { key, deleted:true, shared:false }; },
  async list(prefix){ const keys = Object.keys(window.localStorage).filter(k=>!prefix || k.startsWith(prefix)); return { keys, prefix, shared:false }; }
};

let STORAGE_MODE = 'local';
let STORAGE = LocalStorageBackend;
async function detectarAlmacenamiento(){
  if(await intentarConectarServidorLocal()){ STORAGE_MODE='servidor'; STORAGE=ServerBackend; return; }
  // Firebase (nube) queda APAGADO por defecto: el sistema es de uso local y sus datos viven en
  // data/sigie.db. Solo se usa si se activa a propósito (localStorage 'sigie:usar_firebase' = '1')
  // Y las librerías de Firebase están cargadas en el HTML.
  let permitirFirebase = false;
  try{ permitirFirebase = window.localStorage.getItem('sigie:usar_firebase') === '1'; }catch(e){}
  if(permitirFirebase && await intentarConectarFirebase()){ STORAGE_MODE='firebase'; STORAGE=FirestoreBackend; return; }
  const tieneClaude = (typeof window.storage !== 'undefined' && window.storage !== null && typeof window.storage.get === 'function');
  if(tieneClaude){ STORAGE_MODE='claude'; STORAGE=window.storage; return; }
  STORAGE_MODE='local'; STORAGE=LocalStorageBackend;
}

const DB = {
  cache:{},
  // Cola de escrituras que fallaron (por ejemplo, un corte de red momentáneo):
  // se reintentan solas cada cierto tiempo y también al recuperar la conexión,
  // para no perder cambios que el usuario ya dio por guardados.
  pending:{},
  // --- Solo con el servidor local (v8): control de versiones por clave ---
  versions:{},   // clave -> versión que este navegador leyó/guardó por última vez
  base:{},       // clave -> texto JSON tal como se leyó/guardó por última vez (base de la fusión)
  cola:{},       // clave -> promesa del último guardado (los guardados de una clave van en fila)
  guardando:{},  // clave -> cuántos guardados hay en curso
  alActualizar:null, // función que la app registra para redibujar cuando llegan datos de otros usuarios
  async load(key, fallback){
    try{
      const r = await STORAGE.get(key, false);
      const v = r && r.value !== undefined ? JSON.parse(r.value) : fallback;
      this.cache[key] = v;
      if(STORAGE_MODE==='servidor'){ this.versions[key] = r.version || 0; this.base[key] = r.value !== undefined ? r.value : JSON.stringify(fallback===undefined?null:fallback); }
      return v;
    }catch(e){
      this.cache[key] = fallback;
      if(STORAGE_MODE==='servidor'){ this.versions[key] = 0; this.base[key] = JSON.stringify(fallback===undefined?null:fallback); }
      return fallback;
    }
  },
  // opciones.reemplazar = true → escritura incondicional (restaurar respaldo, reiniciar, datos de ejemplo):
  // el valor guardado REEMPLAZA al del servidor sin fusionar.
  async save(key, value, opciones){
    if(STORAGE_MODE==='servidor') return this._guardarServidor(key, value, opciones||{});
    this.cache[key] = value;
    try{
      await STORAGE.set(key, JSON.stringify(value), false);
      if(this.pending[key]){ delete this.pending[key]; actualizarIndicadorPendientes(); }
    }
    catch(e){ this._avisarFallo(key, value, e); }
    return value;
  },
  _avisarFallo(key, value, e){
    this.pending[key] = value;
    actualizarIndicadorPendientes();
    const detalle = (e && e.message) ? e.message : 'error desconocido';
    toast('No se pudo guardar (se reintentará solo): '+detalle+'. Si subiste una foto o logo muy pesado, usa una imagen más liviana.', 'err');
  },
  _sinClaves(key, v){ // la contraseña en texto plano (nuevaClave) viaja al servidor pero no se queda en memoria
    return (key===KEYS.usuarios && Array.isArray(v)) ? v.map(u=>{ const c = {...u}; delete c.nuevaClave; return c; }) : v;
  },
  async _guardarServidor(key, value, op){
    const texto = JSON.stringify(value);
    this.cache[key] = this._sinClaves(key, value);
    const previa = this.cola[key] || Promise.resolve();
    this.guardando[key] = (this.guardando[key]||0) + 1;
    const trabajo = previa.then(()=>this._enviar(key, texto, op));
    this.cola[key] = trabajo.catch(()=>{});
    try{
      await trabajo;
      if(this.pending[key]===value){ delete this.pending[key]; actualizarIndicadorPendientes(); }
    }catch(e){
      if(e && e.noReintentar){
        // El servidor rechazó el guardado a propósito (sin permiso, datos inválidos): no tiene sentido reintentar.
        toast('No se pudo guardar: '+e.message, 'err');
        // Volver a lo que realmente hay en el servidor. Si la clave aún no existe allá, se vuelve al último valor
        // sincronizado (this.base), NO al que el servidor acaba de rechazar.
        try{ await this.load(key, this.base[key]!==undefined ? JSON.parse(this.base[key]) : undefined); }catch(x){}
      } else {
        this._avisarFallo(key, value, e);
      }
    }finally{ this.guardando[key]--; }
    return this.cache[key];
  },
  async _enviar(key, texto, op){
    for(let intento=0; intento<6; intento++){
      try{
        const r = await STORAGE.set(key, texto, false, op.reemplazar ? undefined : (this.versions[key]||0));
        this.versions[key] = r.version; this.base[key] = texto;
        // Para usuarios, volvemos a leer: así la caché refleja lo que el servidor guardó (sin contraseñas ni hashes).
        if(key===KEYS.usuarios){ try{ await this.load(key, []); }catch(x){} }
        return;
      }catch(e){
        if(!(e && e.conflicto)) throw e;
        // Otro usuario guardó esta clave después de que la leímos: fusionamos su trabajo con el nuestro.
        const fusionado = SigieMerge.fusionar(JSON.parse(this.base[key]), JSON.parse(texto), JSON.parse(e.valorServidor));
        texto = JSON.stringify(fusionado);
        this.versions[key] = e.version; this.base[key] = e.valorServidor;
        this.cache[key] = this._sinClaves(key, fusionado);
      }
    }
    throw new Error('Otros usuarios están guardando lo mismo en este momento. Intenta de nuevo.');
  },
  async delete(key){
    delete this.cache[key];
    delete this.pending[key];
    delete this.versions[key]; delete this.base[key];
    try{ await STORAGE.delete(key); }catch(e){}
  },
  get(key){ return this.cache[key]; },
  async reintentarPendientes(){
    const claves = Object.keys(this.pending);
    if(claves.length===0) return;
    for(const key of claves){
      try{
        if(STORAGE_MODE==='servidor') await this._enviar(key, JSON.stringify(this.pending[key]), {});
        else await STORAGE.set(key, JSON.stringify(this.pending[key]), false);
        delete this.pending[key];
      }
      catch(e){ if(e && e.noReintentar){ delete this.pending[key]; } /* si no, sigue pendiente para el próximo ciclo */ }
    }
    actualizarIndicadorPendientes();
    if(Object.keys(this.pending).length===0) toast('Cambios pendientes sincronizados correctamente.', 'ok');
  },
  // Trae lo que otros usuarios guardaron desde la última vez (solo servidor local).
  // No toca claves con cambios nuestros sin enviar. Devuelve true si algo cambió.
  async sincronizar(){
    if(STORAGE_MODE!=='servidor' || this._sincronizando) return false;
    if(document.querySelector('.modal-bg')) return false;               // con un formulario abierto no cambiamos los datos de debajo
    if(typeof STATE!=='undefined' && STATE.tomaEnCurso) return false;
    this._sincronizando = true;
    let hubo = false;
    try{
      const remotas = await ServerBackend.versiones();
      for(const [key, ver] of Object.entries(remotas)){
        if(this.versions[key]===ver) continue;
        if(this.pending[key] || this.guardando[key]) continue;
        if(key in this.cache || key.startsWith(CARPETA_IMAGENES)){
          const antes = this.base[key];
          await this.load(key, this.cache[key]);
          if(this.base[key]!==antes) hubo = true;
        }
      }
    }catch(e){ /* sin red por ahora: se reintenta en el próximo ciclo */ }
    finally{ this._sincronizando = false; }
    if(hubo) this._renderPendiente = true;
    // Redibujamos solo si el usuario no está escribiendo en un campo.
    if(this._renderPendiente){
      const a = document.activeElement;
      const escribiendo = a && /^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName);
      if(!escribiendo && !document.querySelector('.modal-bg') && typeof this.alActualizar==='function'){
        this._renderPendiente = false;
        try{ this.alActualizar(); }catch(e){ console.warn('No se pudo redibujar tras sincronizar:', e); }
      }
    }
    return hubo;
  }
};
// Pequeño indicador visual (no bloqueante) de cuántas claves tienen cambios sin
// sincronizar todavía; se actualiza solo, sin que el usuario tenga que hacer nada.
function actualizarIndicadorPendientes(){
  const n = Object.keys(DB.pending).length;
  const el = document.getElementById('pendingIndicator');
  if(el) el.textContent = n>0 ? ('⏳ '+n+' cambio(s) pendiente(s) de sincronizar…') : '';
}
function iniciarReintentoAutomatico(){
  setInterval(()=>DB.reintentarPendientes(), 15000);
  window.addEventListener('online', ()=>DB.reintentarPendientes());
  // Con el servidor local: traer cada pocos segundos (y al volver a la pestaña) lo que otros guardaron.
  if(STORAGE_MODE==='servidor'){
    setInterval(()=>DB.sincronizar(), 10000);
    document.addEventListener('visibilitychange', ()=>{ if(!document.hidden) DB.sincronizar(); });
    window.addEventListener('focus', ()=>DB.sincronizar());
  }
}

/* ---------------------------------------------------------------------
   "CARPETA" DE IMÁGENES — cada foto/logo se guarda como un archivo propio
   (una clave independiente sigie:imagenes:<id>), y los bienes/config solo
   guardan el ID de referencia. Así el registro del bien queda liviano y
   cada imagen se puede reemplazar/eliminar sin tocar el resto de los datos.
   --------------------------------------------------------------------- */
const CARPETA_IMAGENES = 'sigie:imagenes:';
async function preloadImagenes(){
  try{
    const r = await STORAGE.list(CARPETA_IMAGENES);
    const keys = (r && r.keys) || [];
    await Promise.all(keys.map(k=>DB.load(k, '')));
  }catch(e){}
}
function imagenSrc(id){ return id ? (DB.get(CARPETA_IMAGENES+id) || '') : ''; }
async function guardarImagen(dataUrl){
  const id = uid('img');
  await DB.save(CARPETA_IMAGENES+id, dataUrl);
  return id;
}
async function eliminarImagen(id){
  if(!id) return;
  await DB.delete(CARPETA_IMAGENES+id);
}
// Compatibilidad: registros guardados antes de crear la carpeta de imágenes
// tenían la foto pegada directo en el campo (foto/logo). Si no hay fotoId/logoId,
// se sigue mostrando esa imagen antigua sin romper nada.
function fotoDelBien(it){ return (it && (imagenSrc(it.fotoId) || it.foto)) || ''; }
function logoDeConfig(cfg){ return (cfg && (imagenSrc(cfg.logoId) || cfg.logo)) || ''; }

