  seq:'sigie:secuencia', seqInterno:'sigie:secuencia_interna', seqPorSBN:'sigie:secuencia_por_sbn', usuarios:'sigie:usuarios', papelera:'sigie:papelera',
  prestamos:'sigie:prestamos', cargos:'sigie:cargos', tomas:'sigie:tomas_inventario', mantenimientos:'sigie:mantenimientos',
  categoriasDeprec:'sigie:categorias_deprec', snapshots:'sigie:inventario_snapshots', bitacora:'sigie:bitacora',
  polizas:'sigie:polizas', conciliaciones:'sigie:conciliaciones', requerimientos:'sigie:requerimientos', seqReq:'sigie:secuencia_requerimientos',
  planos:'sigie:planos', bajas:'sigie:bajas', seqBaja:'sigie:secuencia_bajas',
