// Sugiere la categoría de depreciación a partir de la denominación del bien,
// buscando coincidencias de palabras clave en la tabla de categorías. Si no
// encuentra ninguna, cae en "otros". Se usa para autocompletar el formulario;
// el usuario siempre puede elegir otra categoría manualmente.
function lookupCategoriaDeprec(denominacion, categorias){
  categorias = categorias || DB.get(KEYS.categoriasDeprec) || [];
  const d = (denominacion||'').toUpperCase();
  const hit = categorias.find(c => (c.palabras||[]).some(p=>d.includes(p)));
  if(hit) return hit.id;
  const otros = categorias.find(c=>c.id==='otros');
  return otros ? otros.id : (categorias[0] ? categorias[0].id : '');
}
// Cálculo de depreciación por línea recta (NICSP), sin valor residual:
// Depreciación anual = Valor de adquisición / Vida útil (años de la categoría)
// Depreciación acumulada = mín(Depreciación anual × años transcurridos, Valor de adquisición)
// Valor neto en libros = Valor de adquisición − Depreciación acumulada
// Los años transcurridos se cuentan desde la fecha de registro del bien en el
// sistema y se topan en la vida útil (un bien no se deprecia más allá de su
// valor de adquisición). Devuelve null si el bien no tiene valor de adquisición
// o no tiene una categoría de depreciación válida asignada (no es depreciable).
function calcularDepreciacionItem(it, categorias){
  categorias = categorias || DB.get(KEYS.categoriasDeprec) || [];
  const valor = Number(it.valorAdquisicion);
  const cat = categorias.find(c=>c.id===it.categoriaDeprecId);
  if(!cat || !valor || valor<=0 || !cat.vidaUtilAnios) return null;
  let anios = aniosTranscurridos(it.fechaRegistro);
  if(anios==null) return null;
  if(anios<0) anios = 0;
  const vidaUtil = cat.vidaUtilAnios;
  const aniosEfectivos = Math.min(anios, vidaUtil);
  const depreciacionAnual = valor / vidaUtil;
  const depreciacionAcumulada = Math.min(depreciacionAnual*aniosEfectivos, valor);
  const valorNetoLibros = Math.max(valor - depreciacionAcumulada, 0);
  return {
    categoriaId: cat.id, categoria: cat.nombre, vidaUtilAnios: vidaUtil,
    aniosTranscurridos: anios, depreciacionAnual, depreciacionAcumulada, valorNetoLibros,
    pctDepreciado: valor>0 ? (depreciacionAcumulada/valor*100) : 0,
    totalmenteDepreciado: anios >= vidaUtil
  };
}
function uid(prefix){ return prefix+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }
function money(n){ return 'S/ ' + (Number(n)||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}); }
function esc(s){ return (s===undefined||s===null)?'':String(s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
// Fecha de HOY en hora local (no UTC): en Perú (UTC-5), toISOString() adelantaba un día a partir de las 19:00.
function fechaLocalISO(d){ d = d || new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function today(){ return fechaLocalISO(); }

/* ---------------------------------------------------------------------
   BITÁCORA DE AUDITORÍA — registro de "quién hizo qué y cuándo" para poder
   rendir cuentas ante la UGEL o una auditoría interna. Se usa tanto desde
   index.html/app.js (con sesión ya iniciada) como desde login.html/login.js
   (donde todavía no hay STATE.session, por eso se puede pasar un "actor"
   explícito). Se guarda como una lista simple en KEYS.bitacora; se recorta
   a los últimos 3000 registros para no crecer indefinidamente.
   --------------------------------------------------------------------- */
async function registrarBitacora(accion, detalle, actor){
  const usuario = actor ? (actor.usuario||'—') : (STATE.session ? (STATE.session.nombre||STATE.session.usuario) : '—');
  const rol = actor ? (actor.rol||'—') : (STATE.session ? (STATE.session.rol||'—') : '—');
  const log = DB.get(KEYS.bitacora) || [];
  const nuevo = { id:uid('log'), fecha:new Date().toISOString(), usuario, rol, accion, detalle: detalle||'' };
  let actualizado = [...log, nuevo];
  if(actualizado.length>3000) actualizado = actualizado.slice(actualizado.length-3000);
  await DB.save(KEYS.bitacora, actualizado);
}
// Suma N meses a una fecha ISO (YYYY-MM-DD), usada para calcular la siguiente
// fecha programada de un mantenimiento recurrente.
function sumarMesesISO(fechaISO, meses){
  const f = new Date(fechaISO+'T00:00:00');
  f.setMonth(f.getMonth()+Number(meses));
  return f.toISOString().slice(0,10);
}
function toast(msg, type){
  const wrap = document.getElementById('toasts');
  const el = document.createElement('div');
  el.className = 'toast'+(type==='err'?' err':type==='ok'?' ok':'');
  el.textContent = msg;
  wrap.appendChild(el);
  setTimeout(()=>{ el.style.transition='opacity .4s'; el.style.opacity='0'; setTimeout(()=>el.remove(),400); }, 3200);
}
// Redimensiona y comprime cualquier imagen (logo o foto de un bien) antes de
// convertirla a base64. Una foto de celular sin comprimir puede pesar 3-5 MB y
// superar el límite de tamaño del almacenamiento — por eso todas las imágenes
// pasan por aquí antes de guardarse.
function comprimirImagen(file, maxDim, calidad){
  return new Promise((resolve, reject)=>{
    const reader = new FileReader();
    reader.onerror = ()=>reject(new Error('No se pudo leer el archivo.'));
    reader.onload = ()=>{
      const img = new Image();
      img.onerror = ()=>reject(new Error('El archivo no parece ser una imagen válida.'));
      img.onload = ()=>{
        let { width, height } = img;
        if(width > maxDim || height > maxDim){
          if(width >= height){ height = Math.round(height * (maxDim/width)); width = maxDim; }
          else { width = Math.round(width * (maxDim/height)); height = maxDim; }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width; canvas.height = height;
        canvas.getContext('2d').drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', calidad));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

/* ---------------------------------------------------------------------
   3. AUTENTICACIÓN (control de acceso interno por rol, no es
   ciberseguridad de nivel bancario: sirve para trazabilidad — saber
   quién registró/modificó cada bien — y para limitar lo que ve cada
   docente responsable de aula).
   --------------------------------------------------------------------- */
async function sha256Hex(text){
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
}
function genSalt(){ return Array.from(crypto.getRandomValues(new Uint8Array(12))).map(b=>b.toString(16).padStart(2,'0')).join(''); }
/* ---------------------------------------------------------------------
   Contraseñas: PBKDF2-SHA256 (150 000 iteraciones) con sal aleatoria por usuario.
   Las cuentas antiguas (SHA-256 simple, sin campo "algo") siguen pudiendo
   entrar: al iniciar sesión correctamente se migran solas a PBKDF2.
   --------------------------------------------------------------------- */
const PBKDF2_ITER = 150000;
const PASS_MIN_LARGO = 8;
async function pbkdf2Hex(text, salt){
  const clave = await crypto.subtle.importKey('raw', new TextEncoder().encode(text), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({name:'PBKDF2', hash:'SHA-256', salt:new TextEncoder().encode(salt), iterations:PBKDF2_ITER}, clave, 256);
  return Array.from(new Uint8Array(bits)).map(b=>b.toString(16).padStart(2,'0')).join('');
}
// Devuelve {salt, hash, algo} listo para guardar en el usuario.
async function crearCredencial(pass){
  const salt = genSalt();
  return { salt, hash: await pbkdf2Hex(pass, salt), algo:'pbkdf2' };
}
// Comprueba la contraseña contra un usuario (soporta el formato antiguo).
async function verificarPassword(u, pass){
  if(!u || !u.salt || !u.hash) return false;
  const calculado = u.algo==='pbkdf2' ? await pbkdf2Hex(pass, u.salt) : await sha256Hex(pass+u.salt);
  // comparación en tiempo constante (aprox.) para no filtrar información por tiempos
  if(calculado.length!==u.hash.length) return false;
  let diff = 0; for(let i=0;i<calculado.length;i++) diff |= calculado.charCodeAt(i)^u.hash.charCodeAt(i);
  return diff===0;
}
// Devuelve un texto de error si la contraseña no es aceptable, o '' si está bien.
function validarPasswordNueva(pass){
  if(!pass || pass.length<PASS_MIN_LARGO) return 'La contraseña debe tener al menos '+PASS_MIN_LARGO+' caracteres.';
  if(['admin123','12345678','password','contraseña','contrasena'].includes(pass.toLowerCase())) return 'Esa contraseña es demasiado común. Elige otra.';
  return '';
}
// Con el servidor local, las cuentas iniciales las crea el servidor al arrancar (la API exige sesión).
// Esta versión del navegador solo se usa en los modos de respaldo (archivo abierto con doble clic, etc.).
async function seedAdminIfNeeded(){
  if(STORAGE_MODE==='servidor') return;
  let users = DB.get(KEYS.usuarios);
  if(!users || users.length===0){
    const cred = await crearCredencial('admin123');
    // debeCambiarPass: la primera vez que entre, el sistema le obliga a elegir una contraseña propia.
    users = [{ id:uid('usr'), usuario:'admin', nombre:'Coordinador de Innovación y Soporte Tecnológico (CIST)', rol:'ADMIN', aulaIds:[], ...cred, debeCambiarPass:true }];
    await DB.save(KEYS.usuarios, users);
  }
  // Usuarios iniciales de la biblioteca: se crean UNA sola vez (si luego se borran, no vuelven a aparecer).
  // Todos deben cambiar su contraseña en el primer ingreso.
  const yaSembrados = await DB.load('sigie:bib_usuarios_semilla', false);
  if(!yaSembrados){
    users = [...(DB.get(KEYS.usuarios)||[])];
    const base = [
      ['biblioteca','Bibliotecario(a) responsable','ADMIN2','Biblio2026'],
      ['docente','Docente (registra préstamos)','DOCENTE','Docente2026'],
      ['consulta','Solo consulta','CONSULTA','Consulta2026']
    ];
    for(const [usuario,nombre,rol,pass] of base){
      if(users.some(u=>u.usuario===usuario)) continue;
      users.push({ id:uid('usr'), usuario, nombre, rol, aulaIds:[], ...(await crearCredencial(pass)), debeCambiarPass:true });
    }
    await DB.save(KEYS.usuarios, users);
    await DB.save('sigie:bib_usuarios_semilla', true);
  }
}
// ---- Librerías pesadas: se descargan SOLO cuando se usan ----
// Chart.js (gráficos del panel de bienes), JsBarcode (etiquetas con código de barras) y Tesseract (OCR de
// guías) ya no se cargan al abrir el sistema: la biblioteca no las necesita. Si algo las pide, se bajan
// una vez y quedan en la caché del navegador (el service worker también las guarda).
const LIBRERIAS_BAJO_DEMANDA = {
  chart: 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.0/chart.umd.min.js',
  jsbarcode: 'https://cdnjs.cloudflare.com/ajax/libs/JsBarcode/3.11.5/JsBarcode.all.min.js',
  tesseract: 'https://cdnjs.cloudflare.com/ajax/libs/tesseract.js/5.0.4/tesseract.min.js'
};
const _libsCargando = {};
function cargarLibreria(nombre){
  const url = LIBRERIAS_BAJO_DEMANDA[nombre];
  if(!url) return Promise.reject(new Error('Librería desconocida: '+nombre));
  if(!_libsCargando[nombre]){
    _libsCargando[nombre] = new Promise((resolve, reject)=>{
      const s = document.createElement('script');
      s.src = url;
      s.onload = ()=>resolve();
      s.onerror = ()=>{ delete _libsCargando[nombre]; reject(new Error('No se pudo cargar '+nombre+' (revisa tu conexión a internet).')); };
      document.head.appendChild(s);
    });
  }
  return _libsCargando[nombre];
}

// ---- Sesión con el servidor local (cookie HttpOnly: JavaScript no puede leerla ni copiarla) ----
async function cargarSesionServidor(){
  try{
    const r = await fetch('/api/session', { cache:'no-store' });
    if(!r.ok) return null;
    const d = await r.json();
    return (d && d.ok && !d.debeCambiarPass) ? d.sesion : null;
  }catch(e){ return null; }
}
async function cerrarSesionServidor(){ try{ await fetch('/api/logout', { method:'POST' }); }catch(e){} }
// Credencial para guardar en un usuario. Con el servidor local basta enviar la clave: el servidor la hashea y
// nunca devuelve el hash. En los modos de respaldo se hashea aquí como antes.
async function prepararCredencialUsuario(pass){
  return STORAGE_MODE==='servidor' ? { nuevaClave: pass } : await crearCredencial(pass);
}
function currentUser(){ return STATE.session; }
// ADMIN y ADMIN2 tienen los mismos permisos administrativos en todo el sistema.
// La única diferencia es el módulo "Usuarios y accesos": solo ADMIN puede entrar ahí
// (ver puedeGestionarUsuarios más abajo). Así se puede delegar la administración diaria
// sin dar a esa persona la capacidad de crear/editar otras cuentas ni cambiar roles.
function isAdmin(){ return STATE.session && (STATE.session.rol==='ADMIN' || STATE.session.rol==='ADMIN2'); }
// Solo ADMIN (no ADMIN2) puede gestionar usuarios y accesos.
function puedeGestionarUsuarios(){ return STATE.session && STATE.session.rol==='ADMIN'; }
// Solo el rol DOCENTE está restringido a sus aulas asignadas. ADMIN, ADMIN2 y CONSULTA ven todo
// (CONSULTA existe para que un director/UGEL revise y exporte, sin poder modificar nada).
function misAulaIds(){
  if(STATE.session && STATE.session.rol==='DOCENTE') return (STATE.session.aulaIds || []);
  return null; // null = sin restricción de aula
}
function puedoVerAula(aulaId){ const mis = misAulaIds(); return mis===null || mis.includes(aulaId); }
// Permiso de creación/edición/eliminación (ADMIN, ADMIN2 y DOCENTE). CONSULTA es de solo lectura.
function canEdit(){ return STATE.session && (STATE.session.rol==='ADMIN' || STATE.session.rol==='ADMIN2' || STATE.session.rol==='DOCENTE'); }
function guardEdit(){ if(!canEdit()){ toast('Tu rol es de solo consulta: no puedes crear ni editar registros.', 'err'); return false; } return true; }

/* ---------------------------------------------------------------------
   PWA / MODO SIN INTERNET — registra el service worker (sw.js) para que la
   interfaz y las librerías de terceros (Chart.js, QR, código de barras,
   Excel) queden cacheadas y el sistema siga funcionando sin internet,
   mientras el servidor local (server.js) siga corriendo en la red del
   colegio. También permite "instalar" SIGIE como app desde el navegador.
   Se registra desde core.js porque lo cargan tanto index.html como
   login.html. Si el navegador no soporta service workers (o el sistema no
   se abrió por http/https, p.ej. abriendo el archivo directamente), no
   pasa nada: el sistema sigue funcionando normal, solo sin modo offline.
   --------------------------------------------------------------------- */
if('serviceWorker' in navigator){
  window.addEventListener('load', ()=>{
    navigator.serviceWorker.register('sw.js').catch(err=>console.warn('No se pudo activar el modo sin internet (service worker):', err));
  });
}
